steps.initScript:
window.__note = {
  node: () => [...document.querySelectorAll('[data-jfss-collection-note]')].find(x => x.getClientRects().length > 0) || null,
  all: () => document.querySelectorAll('[data-jfss-collection-note]').length,
  text: () => { const n = window.__note.node(); return n ? n.querySelector('.jfss-ac-note-text').textContent : null; },
  page: () => [...document.querySelectorAll('#itemDetailPage')].find(x => !x.classList.contains('hide') && x.getClientRects().length > 0) || null,
  details: (id) => '/web/index.html#/details?id=' + id + '&serverId=' + ApiClient.serverId(),
  shown: (id) => { const p = window.__note.page(); return !!p && new URLSearchParams(location.hash.split('?')[1] || '').get('id') === id && !!p.querySelector('.detailPagePrimaryContainer, .detailPageSecondaryContainer'); },
  misses: () => window.__jfkit.jfss.instance.health.missing().map(m => m.anchor)
};

